-- IARA Educa — 099.10 · Ideb das escolas municipais (dado oficial do INEP)
-- Fonte: INEP, “Ideb — Resultados” (painel em Power BI e planilhas de divulgação), edição 2025 publicada em 05/08/2026, com a série 2005–2025:
--   divulgacao_anos_iniciais_escolas_2025.xlsx e divulgacao_anos_iniciais_municipios_2025.xlsx (download.inep.gov.br/ideb/resultados/).
-- Rede municipal de Maringá, anos iniciais: Ideb, meta (só o 1º ciclo, 2007–2021), aprovação (fração de 0 a 1), indicador de rendimento (P),
-- notas do Saeb (matemática e língua portuguesa) e nota padronizada (N). Marcas do INEP guardadas em obs: “ND” = participação no Saeb
-- insuficiente para divulgar; “-” = sem dado. O Ideb da rede é o do INEP (recalculado pelos alunos), não a média das escolas.
-- Dado público: a ficha da unidade, o mapa e o painel da rede valem também sem login.
-- Após aplicar: reaplicar 20261003009900_privilegios.sql.
begin;

create table if not exists iara.ideb_rede (
  ano smallint primary key,
  ideb numeric(3, 1),
  meta numeric(3, 1),
  aprovacao numeric(6, 4),
  indicador_rendimento numeric(8, 6),
  nota_mat numeric(6, 2),
  nota_lp numeric(6, 2),
  nota_padronizada numeric(8, 6)
);
create table if not exists iara.ideb_escolas (
  inep text not null,
  ano smallint not null,
  nome_inep text not null,
  ideb numeric(3, 1),
  meta numeric(3, 1),
  aprovacao numeric(6, 4),
  indicador_rendimento numeric(8, 6),
  nota_mat numeric(6, 2),
  nota_lp numeric(6, 2),
  nota_padronizada numeric(8, 6),
  obs text,
  primary key (inep, ano)
);
alter table iara.ideb_rede enable row level security;
alter table iara.ideb_escolas enable row level security;

on conflict (ano) do update set ideb = excluded.ideb, meta = excluded.meta, aprovacao = excluded.aprovacao, indicador_rendimento = excluded.indicador_rendimento, nota_mat = excluded.nota_mat, nota_lp = excluded.nota_lp, nota_padronizada = excluded.nota_padronizada;

on conflict (inep, ano) do update set nome_inep = excluded.nome_inep, ideb = excluded.ideb, meta = excluded.meta, aprovacao = excluded.aprovacao, indicador_rendimento = excluded.indicador_rendimento, nota_mat = excluded.nota_mat, nota_lp = excluded.nota_lp, nota_padronizada = excluded.nota_padronizada, obs = excluded.obs;

create or replace function iara.ideb_ultimo_ano() returns smallint
language sql stable security definer set search_path = iara, public
as $$ select max(ano) from iara.ideb_rede where ideb is not null $$;

-- ficha da unidade (público)
create or replace function api.ideb_unidade(p jsonb) returns jsonb
language plpgsql stable security definer set search_path = iara, public
as $$
declare
  v_inep text := (select inep_code from iara.education_units where id = (p ->> 'unit_id')::int);
  v_ult smallint := iara.ideb_ultimo_ano();
begin
  if v_inep is null or not exists (select 1 from iara.ideb_escolas where inep = v_inep) then
    return jsonb_build_object('tem', false, 'motivo', 'O INEP divulga o Ideb das escolas com anos iniciais do ensino fundamental (1º ao 5º ano); CMEIs não têm Ideb.');
  end if;
  return jsonb_build_object('tem', true, 'inep', v_inep, 'nome_inep', (select nome_inep from iara.ideb_escolas where inep = v_inep order by ano desc limit 1),
    'ultimo_ano', v_ult,
    'serie', (select jsonb_agg(jsonb_build_object('ano', e.ano, 'ideb', e.ideb, 'meta', e.meta, 'aprovacao', e.aprovacao, 'nota_mat', e.nota_mat, 'nota_lp', e.nota_lp,
               'nota_padronizada', e.nota_padronizada, 'obs', e.obs, 'rede', r.ideb) order by e.ano) from iara.ideb_escolas e left join iara.ideb_rede r on r.ano = e.ano where e.inep = v_inep),
    'posicao', (select jsonb_build_object('posicao', z.pos, 'de', z.n) from (
                  select inep, rank() over (order by ideb desc) pos, count(*) over () n from iara.ideb_escolas where ano = v_ult and ideb is not null) z where z.inep = v_inep),
    'fonte', jsonb_build_object('rotulo', 'INEP · Ideb 2005–2025 (divulgado em 05/08/2026)', 'url', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/pesquisas-estatisticas-e-indicadores/ideb/resultados'),
    'nota', 'ND: participação no Saeb insuficiente para divulgar. Metas: só as do 1º ciclo (2007–2021); 2023 e 2025 não têm meta.');
end $$;

-- painel da rede (público): série da rede, escolas no último ano, evolução e quem está abaixo de 6,0
create or replace function api.ideb_rede(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = iara, public
as $$
declare
  v_ult smallint := iara.ideb_ultimo_ano();
begin
  return jsonb_build_object('ultimo_ano', v_ult,
    'rede', (select jsonb_agg(jsonb_build_object('ano', ano, 'ideb', ideb, 'meta', meta, 'aprovacao', aprovacao, 'nota_mat', nota_mat, 'nota_lp', nota_lp) order by ano) from iara.ideb_rede),
    'escolas', (select coalesce(jsonb_agg(jsonb_build_object('inep', e.inep, 'nome', coalesce(u.short_name, initcap(lower(e.nome_inep))), 'unit_id', u.id, 'regiao', t.name,
                  'ideb', e.ideb, 'obs', e.obs, 'anterior', a.ideb, 'variacao', e.ideb - a.ideb, 'aprovacao', e.aprovacao, 'nota_mat', e.nota_mat, 'nota_lp', e.nota_lp)
                  order by e.ideb desc nulls last, u.short_name), '[]')
                from iara.ideb_escolas e
                left join iara.ideb_escolas a on a.inep = e.inep and a.ano = v_ult - 2
                left join iara.education_units u on u.inep_code = e.inep
                left join iara.territories t on t.id = u.macro_territory_id
                where e.ano = v_ult),
    'resumo', (select jsonb_build_object('escolas', count(*), 'com_ideb', count(ideb), 'media_simples', round(avg(ideb), 1), 'maior', max(ideb), 'menor', min(ideb),
                 'abaixo_6', count(*) filter (where ideb < 6), 'acima_7', count(*) filter (where ideb >= 7),
                 'subiram', (select count(*) from iara.ideb_escolas x join iara.ideb_escolas y on y.inep = x.inep and y.ano = v_ult - 2 where x.ano = v_ult and x.ideb > y.ideb),
                 'cairam', (select count(*) from iara.ideb_escolas x join iara.ideb_escolas y on y.inep = x.inep and y.ano = v_ult - 2 where x.ano = v_ult and x.ideb < y.ideb))
               from iara.ideb_escolas where ano = v_ult),
    'fonte', jsonb_build_object('rotulo', 'INEP · Ideb 2005–2025 (divulgado em 05/08/2026)', 'url', 'https://www.gov.br/inep/pt-br/areas-de-atuacao/pesquisas-estatisticas-e-indicadores/ideb/resultados'),
    'nota', 'O Ideb da rede é o calculado pelo INEP com os alunos da rede, não a média das escolas. Metas só no 1º ciclo (2007–2021).');
end $$;

-- mapa (público): Ideb de cada escola no último ano, faixas fixas
create or replace function api.ideb_mapa(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = iara, public
as $$
declare
  v_ult smallint := iara.ideb_ultimo_ano();
begin
  return jsonb_build_object('modo', 'taxa', 'sufixo', '', 'max', null,
    'pontos', (select coalesce(jsonb_agg(jsonb_build_object('lat', u.lat, 'lng', u.lng, 'valor', e.ideb,
                 'titulo', format('%s: Ideb %s em %s%s', u.short_name, replace(e.ideb::text, '.', ','), v_ult,
                                  coalesce(format(' (%s em %s)', replace(a.ideb::text, '.', ','), v_ult - 2), '')),
                 'cor', case when e.ideb >= 7 then '#16A34A' when e.ideb >= 6 then '#EAB308' else '#DC2626' end)), '[]')
               from iara.ideb_escolas e join iara.education_units u on u.inep_code = e.inep
               left join iara.ideb_escolas a on a.inep = e.inep and a.ano = v_ult - 2
               where e.ano = v_ult and e.ideb is not null),
    'legenda', jsonb_build_array(jsonb_build_object('cor', '#DC2626', 'rotulo', 'Abaixo de 6,0'), jsonb_build_object('cor', '#EAB308', 'rotulo', '6,0 a 6,9'),
                                 jsonb_build_object('cor', '#16A34A', 'rotulo', '7,0 ou mais')),
    'resumo', jsonb_build_array(
      jsonb_build_object('rotulo', format('Ideb da rede em %s', v_ult), 'valor', (select ideb from iara.ideb_rede where ano = v_ult)),
      jsonb_build_object('rotulo', 'Escolas abaixo de 6,0', 'valor', (select count(*) from iara.ideb_escolas where ano = v_ult and ideb < 6)),
      jsonb_build_object('rotulo', 'Escolas com 7,0 ou mais', 'valor', (select count(*) from iara.ideb_escolas where ano = v_ult and ideb >= 7))),
    'ranking', jsonb_build_object('titulo', 'Escolas com o menor Ideb', 'itens', (select coalesce(jsonb_agg(jsonb_build_object('nome', coalesce(u.short_name, e.nome_inep), 'valor', e.ideb, 'sufixo', '',
                 'detalhe', coalesce(format('%s em %s', replace(a.ideb::text, '.', ','), v_ult - 2), 'sem Ideb anterior')) order by e.ideb), '[]')
               from (select * from iara.ideb_escolas where ano = v_ult and ideb is not null order by ideb limit 10) e
               left join iara.education_units u on u.inep_code = e.inep left join iara.ideb_escolas a on a.inep = e.inep and a.ano = v_ult - 2)),
    'nota', format('INEP, Ideb %s (anos iniciais). Dado oficial e público.', v_ult));
end $$;

-- Oráculo
on conflict (tema) do update set rotulo = excluded.rotulo, palavras = excluded.palavras;
 $q$select case when $2 then (select ideb from iara.ideb_rede where ano = iara.ideb_ultimo_ano()) else (select round(avg(e.ideb), 1) from iara.ideb_escolas e join iara.education_units u on u.inep_code = e.inep where e.ano = iara.ideb_ultimo_ano() and u.id = any ($1)) end$q$,
 false, null, 1, '\mideb', '\mideb', 'menor', 1),
('ideb.abaixo6', 'ideb', 'Escolas com Ideb abaixo de 6,0',
 $q$select count(*) from iara.ideb_escolas e join iara.education_units u on u.inep_code = e.inep where e.ano = iara.ideb_ultimo_ano() and e.ideb < 6 and u.id = any ($1)$q$,
 false, null, 0, '\mabaixo', null, 'maior', 2),
('ideb.aprovacao', 'ideb', 'Aprovação do 1º ao 5º ano (INEP)',
 $q$select case when $2 then (select round(aprovacao * 100, 1) from iara.ideb_rede where ano = iara.ideb_ultimo_ano()) else (select round(avg(e.aprovacao) * 100, 1) from iara.ideb_escolas e join iara.education_units u on u.inep_code = e.inep where e.ano = iara.ideb_ultimo_ano() and u.id = any ($1)) end$q$,
 false, '%', 1, '\maprovac', '\maprovac', 'menor', 3),
('ideb.mat', 'ideb', 'Nota do Saeb em matemática (5º ano)',
 $q$select case when $2 then (select nota_mat from iara.ideb_rede where ano = iara.ideb_ultimo_ano()) else (select round(avg(e.nota_mat), 1) from iara.ideb_escolas e join iara.education_units u on u.inep_code = e.inep where e.ano = iara.ideb_ultimo_ano() and u.id = any ($1)) end$q$,
 false, null, 1, '\mmatematica', '\mmatematica', 'menor', 4),
('ideb.lp', 'ideb', 'Nota do Saeb em língua portuguesa (5º ano)',
 $q$select case when $2 then (select nota_lp from iara.ideb_rede where ano = iara.ideb_ultimo_ano()) else (select round(avg(e.nota_lp), 1) from iara.ideb_escolas e join iara.education_units u on u.inep_code = e.inep where e.ano = iara.ideb_ultimo_ano() and u.id = any ($1)) end$q$,
 false, null, 1, '\mportugues|\mleitura', '\mportugues', 'menor', 5)
on conflict (chave) do update set tema = excluded.tema, rotulo = excluded.rotulo, consulta = excluded.consulta, pessoas = excluded.pessoas, sufixo = excluded.sufixo,
  casas = excluded.casas, palavras = excluded.palavras, palavras_ranking = excluded.palavras_ranking, pior = excluded.pior, ordem = excluded.ordem;

select r, 'ideb.read' from unnest(array['PREFEITO', 'SECRETARIO', 'SUPERINTENDENCIA', 'GERENCIA_EI', 'INOVACAO', 'CONTROLE_EXTERNO', 'TRIBUNAL_CONTAS', 'CONSELHOS', 'CAMARA',
                                        'DIRETOR_UNIDADE', 'ANALISTA_CENTRAL']) r
on conflict do nothing;

commit;
